let centreX,centreY,rows,cols,packagingImage,w=window.innerWidth,h=window.innerHeight,defScale=5,circleScale=defScale,defSpace=10,gridSpace=defSpace,defSample=12,pixelSample=defSample;const halftoneColour="#0d0c1d",backgroundColour="#f8eee6";function centreImage(){cols=packagingImage.width/pixelSample,rows=packagingImage.height/pixelSample,centreX=w/2-cols*gridSpace/2,centreY=h/2-rows*gridSpace/2}function drawHalftone(){for(let e=0;e<cols;e++)for(let a=0;a<rows;a++){let t=alpha(packagingImage.get(e*pixelSample,a*pixelSample));if(t>15){let n=map(t,20,255,0,1);circle(e*gridSpace+centreX,a*gridSpace+centreY,circleScale*n)}}}function setup(){createCanvas(w,h),noLoop(),loadImage("./assets/wordmark.png",e=>{packagingImage=e,centreImage(),draw()}),document.getElementById("exportSVG").addEventListener("click",()=>{draw(),save("OmbreExport.svg")}),document.querySelector("#getImgButton").addEventListener("input",e=>{if(!e.target.files.length)return void loadImage("./assets/wordmark.png",()=>{centreImage(),draw()});let a=new FileReader;a.onloadend=()=>{loadImage(a.result,e=>{packagingImage=e,centreImage(),draw()})},a.readAsDataURL(e.target.files[0])});let e=document.getElementById("sizeSlider");e.addEventListener("input",()=>{circleScale=map(e.value,0,100,+defScale,5*defScale),gridSpace=map(e.value,0,100,+defSpace,2*defSpace),centreImage(),draw()}),draw()}function draw(){background("#f8eee6"),noStroke(),fill("#0d0c1d"),drawHalftone()}function windowResized(){resizeCanvas(windowWidth,windowHeight),w=windowWidth,h=windowHeight,centreImage(),draw()}